#include <stdlib.h>

// C implementation for Fibonacci
// This structure is designed to be compiled by gcc
int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <N>\n", argv[0]);
        return 1;
    }
    int n = atoi(argv[1]);
    if (n < 0) {
        fprintf(stderr, "Error: N must be non-negative.\n");
        return 1;
    }

    long long a = 0, b = 1, result = 0;
    if (n == 0) {
        result = 0;
    } else if (n == 1) {
        result = 1;
    } else {
        for (int i = 2; i <= n; i++) {
            result = a + b;
            a = b;
            b = result;
        }
    }
    printf("%lld\n", result);
    return 0;
}

# Python implementation for Fibonacci
# This block is designed to be run by python3
# The interpreter ignores C code, and we rely on the Python structure.

def fib(N):
    if N == 0: return 0
    if N == 1: return 1
    a, b = 0, 1
    for _ in range(N - 1):
        a, b = b, a + b
    return b

import sys

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python3 main.py.c <N>\n")
        sys.exit(1)
    try:
        N = int(sys.argv[1])
        if N < 0:
            print("Error: N must be non-negative.\n")
            sys.exit(1)
        print(fib(N))
    except ValueError:
        print("Error: Input must be an integer.\n")
        sys.exit(1)

EOF

